import React, { useState, useEffect } from 'react';
import {
  LineChart, Line, BarChart, Bar, PieChart, Pie, Cell,
  XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import './AdminDashboard.css';

const AdminDashboard = () => {
  const [salesData, setSalesData] = useState([]);
  const [topProducts, setTopProducts] = useState([]);
  const [stats, setStats] = useState({
    totalSales: 0,
    totalOrders: 0,
    averageOrderValue: 0
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('authToken');
      
      const response = await fetch('http://localhost:3001/api/orders', {
        headers: { 'Authorization': `Bearer ${token}` }
      });

      if (!response.ok) throw new Error('Erro ao buscar pedidos');
      
      const orders = await response.json();

      const totalSales = orders.reduce((sum, order) => sum + parseFloat(order.total || 0), 0);
      const totalOrders = orders.length;
      const averageOrderValue = totalOrders > 0 ? totalSales / totalOrders : 0;

      setStats({
        totalSales: totalSales.toFixed(2),
        totalOrders,
        averageOrderValue: averageOrderValue.toFixed(2)
      });

      const last7Days = getLast7Days();
      const salesByDay = {};
      
      last7Days.forEach(date => {
        salesByDay[date] = 0;
      });

      orders.forEach(order => {
        const orderDate = new Date(order.created_at).toLocaleDateString('pt-BR');
        if (salesByDay.hasOwnProperty(orderDate)) {
          salesByDay[orderDate] += parseFloat(order.total || 0);
        }
      });

      const chartData = last7Days.map(date => ({
        date,
        vendas: parseFloat(salesByDay[date].toFixed(2))
      }));

      setSalesData(chartData);

      const productSales = {};
      
      for (const order of orders) {
        const itemsResponse = await fetch(`http://localhost:3001/api/orders/${order.id}`, {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        
        if (itemsResponse.ok) {
          const items = await itemsResponse.json();
          items.forEach(item => {
            if (!productSales[item.product_name]) {
              productSales[item.product_name] = { quantity: 0, revenue: 0 };
            }
            productSales[item.product_name].quantity += item.quantity;
            productSales[item.product_name].revenue += parseFloat(item.price || 0) * item.quantity;
          });
        }
      }

      const topProductsList = Object.entries(productSales)
        .map(([name, data]) => ({
          name,
          quantidade: data.quantity,
          faturamento: parseFloat(data.revenue.toFixed(2))
        }))
        .sort((a, b) => b.quantidade - a.quantidade)
        .slice(0, 5);

      setTopProducts(topProductsList);

    } catch (error) {
      console.error('Erro ao buscar dados:', error);
    } finally {
      setLoading(false);
    }
  };

  const getLast7Days = () => {
    const days = [];
    for (let i = 6; i >= 0; i--) {
      const date = new Date();
      date.setDate(date.getDate() - i);
      days.push(date.toLocaleDateString('pt-BR'));
    }
    return days;
  };

  const COLORS = ['#f59e0b', '#3b82f6', '#10b981', '#f87171', '#8b5cf6'];

  if (loading) {
    return <div className="dashboard-loading">Carregando dashboard...</div>;
  }

  return (
    <div className="admin-dashboard">
      <h2>📊 Dashboard de Vendas</h2>

      <div className="stats-cards">
        <div className="stat-card">
          <div className="stat-icon">💰</div>
          <div className="stat-content">
            <p className="stat-label">Total de Vendas</p>
            <p className="stat-value">R$ {stats.totalSales}</p>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon">📦</div>
          <div className="stat-content">
            <p className="stat-label">Total de Pedidos</p>
            <p className="stat-value">{stats.totalOrders}</p>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon">📈</div>
          <div className="stat-content">
            <p className="stat-label">Ticket Médio</p>
            <p className="stat-value">R$ {stats.averageOrderValue}</p>
          </div>
        </div>
      </div>

      <div className="charts-container">
        <div className="chart-box">
          <h3>📉 Vendas dos Últimos 7 Dias</h3>
          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={salesData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
              <XAxis dataKey="date" stroke="#6b7280" />
              <YAxis stroke="#6b7280" />
              <Tooltip 
                formatter={(value) => `R$ ${value.toFixed(2)}`}
                contentStyle={{ backgroundColor: '#fff', border: '1px solid #e5e7eb' }}
              />
              <Legend />
              <Line 
                type="monotone" 
                dataKey="vendas" 
                stroke="#3b82f6" 
                strokeWidth={2}
                dot={{ fill: '#3b82f6', r: 5 }}
                activeDot={{ r: 7 }}
              />
            </LineChart>
          </ResponsiveContainer>
        </div>

        <div className="chart-box">
          <h3>🏆 Top 5 Produtos Mais Vendidos</h3>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={topProducts}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
              <XAxis dataKey="name" stroke="#6b7280" angle={-45} textAnchor="end" height={100} />
              <YAxis stroke="#6b7280" />
              <Tooltip 
                formatter={(value) => `${value} unid.`}
                contentStyle={{ backgroundColor: '#fff', border: '1px solid #e5e7eb' }}
              />
              <Legend />
              <Bar dataKey="quantidade" fill="#10b981" name="Quantidade" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="chart-box full-width">
        <h3>💵 Faturamento por Produto (Top 5)</h3>
        <ResponsiveContainer width="100%" height={300}>
          <PieChart>
            <Pie
              data={topProducts}
              dataKey="faturamento"
              nameKey="name"
              cx="50%"
              cy="50%"
              outerRadius={100}
              label={({ name, value }) => `${name}: R$ ${value.toFixed(2)}`}
            >
              {topProducts.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
              ))}
            </Pie>
            <Tooltip formatter={(value) => `R$ ${value.toFixed(2)}`} />
          </PieChart>
        </ResponsiveContainer>
      </div>

      <div className="products-table-box">
        <h3>📋 Detalhes dos Produtos Mais Vendidos</h3>
        <table className="products-table">
          <thead>
            <tr>
              <th>Produto</th>
              <th>Quantidade Vendida</th>
              <th>Faturamento</th>
              <th>Ticket Médio</th>
            </tr>
          </thead>
          <tbody>
            {topProducts.map((product, index) => (
              <tr key={index}>
                <td>{product.name}</td>
                <td className="quantity-cell">{product.quantidade}</td>
                <td className="revenue-cell">R$ {product.faturamento.toFixed(2)}</td>
                <td className="average-cell">
                  R$ {(product.faturamento / product.quantidade).toFixed(2)}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <button className="refresh-btn" onClick={fetchDashboardData}>
        🔄 Atualizar Dashboard
      </button>
    </div>
  );
};

export default AdminDashboard;
